const out = [];
for (const el of document.querySelectorAll('a[onclick], div[onclick], img[onclick]')) {
  const onc = el.getAttribute('onclick') || '';
  if (!onc) continue;
  const r = el.getBoundingClientRect();
  const t = (el.textContent || el.getAttribute('alt') || '').trim().slice(0,40);
  out.push({t, onclick: onc, x: Math.round(r.x+r.width/2), y: Math.round(r.y+r.height/2), w: Math.round(r.width), h: Math.round(r.height)});
}
return JSON.stringify(out);

const out = [];
for (const el of document.querySelectorAll('*')) {
  const cs = getComputedStyle(el);
  if (cs.cursor !== 'pointer' || cs.display === 'none') continue;
  const r = el.getBoundingClientRect();
  if (r.width < 50 || r.height < 50 || r.x < 316 || r.x > 1100) continue;
  const txt = (el.textContent || '').trim().slice(0, 30);
  if (txt) out.push({t: txt, x: Math.round(r.x+r.width/2), y: Math.round(r.y+r.height/2), tag: el.tagName, onc: (el.getAttribute('onclick')||'').slice(0,60)});
}
return JSON.stringify(out, null, 1);

