  const txt = (el.textContent || '').trim().slice(0, 60);
  const dp = el.getAttribute('data-passage') || '';
  const onc = (el.getAttribute('onclick') || '').slice(0, 80);
  out.push({t: txt, dp, onc, x: Math.round(r.x+r.width/2), y: Math.round(r.y+r.height/2)});
}
return JSON.stringify(out, null, 1);

