const wrap = [...document.querySelectorAll('.image-wrapper')].find(el => el.querySelector('span')?.textContent.trim() === 'Restaurant');
return JSON.stringify({
  outerHTML: wrap.outerHTML.slice(0,500),
  parent_handler: wrap.onclick ? 'has' : 'none',
  events: Object.keys(wrap).filter(k => k.startsWith('on'))
});

const container = document.querySelector('.newCityMap-container');
return JSON.stringify({
  has_handler: container.onclick ? 'yes' : 'no',
  events: Object.keys(container).filter(k => k.startsWith('on')),
  parent_attrs: container.getAttributeNames()
});

const v = SugarCube.State.variables;
const npcs = {};
for (const [k,n] of Object.entries(v.npc)) {
  if (n && typeof n === 'object' && (n.location || n.arousal !== undefined)) {
    npcs[k] = {loc: n.location, arousal: n.arousal, corruption: n.corruption, name: n.name||n.title||k};
  }
}
return JSON.stringify({
  time: v.game.time, day: v.game.day, energy: v.player.energy, money: v.player.money,
  intelligence: v.player.intelligence, exhibitionism: v.player.exhibitionism, corruption: v.player.corruption,
  location: v.player.location,
  npc_with_location: npcs
}, null, 1);

